```java
import java.util.*;

public class Main {
    // 计算最大公因数
    public static int gcd(int a, int b) {
        while (b != 0) {
            int temp = a;
            a = b;
            b = temp % b;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();  // 读取粘合剂的数量
        int[] a = new int[n];

        // 读取所有粘合剂的粘合度
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int min_gcd = a[0];
        int max_gcd = a[0];

        // 遍历所有粘合剂，更新最小值和最大公因数
        for (int i = 1; i < n; i++) {
            min_gcd = gcd(min_gcd, a[i]);
            max_gcd = Math.max(max_gcd, a[i]);
        }

        // 输出最小和最大粘合度
        System.out.println(min_gcd + " " + max_gcd);
    }
}
```

