### Python

```python
def main():
    n = int(input())
    f = list(map(int, input().split()))

    # 计算所有频率的最大公因子，初始为 f[0]
    min_freq = f[0]
    # 记录最高频率
    max_freq = f[0]

    for i in range(1, n):
        import math
        min_freq = math.gcd(min_freq, f[i])
        if f[i] > max_freq:
            max_freq = f[i]

    print(min_freq, max_freq)

if __name__ == "__main__":
