import java.util.Scanner;

public class Main {
    // 计算两个数的最大公因子（辗转相除法）
    public static int gcd(int a, int b) {
        while (b != 0) {
            int temp = a;
            a = b;
            b = temp % b;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] f = new int[n];

        for (int i = 0; i < n; i++) {
            f[i] = sc.nextInt();
        }

        int minFreq = f[0];
        int maxFreq = f[0];

        for (int i = 1; i < n; i++) {
            minFreq = gcd(minFreq, f[i]);
            if (f[i] > maxFreq) {
                maxFreq = f[i];
            }
        }

        System.out.println(minFreq + " " + maxFreq);
        sc.close();
    }
}
